insert into public.activities
  (slug, title, short_description, description, min_age, max_age, duration, category, location, materials, material_tags, adult_help, preparation, steps, tip, premium)
values
  ('tesoros-de-la-cocina', 'Tesoros de la cocina', 'Vasos, cucharas y tapas para sacar, mirar y volver a guardar.', 'Llena una caja con cosas grandes y seguras de la cocina y deja que tu hijo las explore a su ritmo.', 2, 3, 15, 'aprender', 'casa', array['caja de cartón', 'vasos plásticos', 'cucharas de madera', 'tapas grandes', 'un trapo de cocina']::text[], array['carton']::text[], true, '2 minutos.', array['Pon en una caja 6 u 8 objetos grandes de la cocina.', 'Siéntate a su lado y déjalo sacar todo.', 'Nombra cada cosa cuando la tome: vaso, cuchara, tapa.', 'Al final, guarden todo juntos en la caja.']::text[], 'Usa solo objetos grandes que no quepan en su boca y quédate a su lado.', false),
  ('bolos-con-botellas', 'Bolos con botellas', 'Botellas vacías, una pelota y a tumbar.', 'Arma una pista de bolos con botellas plásticas vacías y túrnense para lanzar la pelota.', 3, 5, 15, 'moverse', 'casa', array['6 botellas plásticas vacías', 'una pelota']::text[], array['nada']::text[], false, '1 minuto.', array['Pon las botellas en triángulo al final de un pasillo.', 'Marca con un zapato desde dónde se lanza.', 'Túrnense para rodar la pelota y cuenten cuántas caen.', 'Vuelvan a pararlas y jueguen otra ronda.']::text[], 'Si se caen muy fácil, ponle un poco de agua a cada botella.', true),
  ('la-tiendita', 'La tiendita', 'Una tienda de verdad con lo que hay en la despensa.', 'Monten una tienda con productos de la despensa y billetes dibujados en papel. Uno vende y otro compra.', 3, 5, 30, 'juntos', 'casa', array['productos de la despensa', 'papel', 'colores', 'una bolsa']::text[], array['papel', 'colores']::text[], true, '5 minutos.', array['Dibujen juntos unos billetes en papel.', 'Pongan los productos sobre una mesa.', 'Uno es el tendero y el otro el cliente.', 'Cambien de papel en la siguiente ronda.']::text[], 'Pídele que cuente los billetes al pagar: practica números sin darse cuenta.', true),
  ('flota-o-se-hunde', '¿Flota o se hunde?', 'Un experimento con agua y cosas de la casa.', 'Antes de soltar cada objeto en el agua, adivinen si va a flotar o se va a hundir.', 3, 5, 15, 'aprender', 'casa', array['un recipiente con agua', 'una toalla', 'objetos de la casa: tapa, cuchara, corcho, piedra']::text[], array['nada']::text[], true, '2 minutos.', array['Pon el recipiente con agua sobre una toalla.', 'Muestra un objeto y pregunta: ¿flota o se hunde?', 'Suéltalo en el agua y miren qué pasa.', 'Separen los que flotan de los que se hunden.']::text[], 'Quédate siempre a su lado mientras haya agua.', true),
  ('el-camino-de-cintas', 'El camino de cintas', 'Cuatro tiras de cinta y un circuito para saltar sin parar.', 'Pega tiras de cinta de colores en el piso y arma un circuito: saltar, caminar en puntas o en un pie.', 4, 5, 15, 'moverse', 'casa', array['cinta de enmascarar de colores']::text[], array['cinta']::text[], false, '2 minutos.', array['Pega 4 o 5 tiras de cinta en el piso, separadas un paso.', 'Asigna un movimiento a cada color: saltar, en puntas, en un pie.', 'Que recorra el camino haciendo cada movimiento.', 'Cambien las reglas en cada vuelta.']::text[], 'Despega la cinta despacio al final para no dañar el piso.', false),
  ('carrera-de-cucharas', 'Carrera de cucharas', 'Llevar una bolita de papel sin que se caiga.', 'Una carrera lenta y divertida: llevar una bolita de papel en una cuchara de un lado al otro de la sala.', 4, 5, 5, 'moverse', 'casa', array['una cuchara', 'una hoja de papel']::text[], array['papel']::text[], false, '1 minuto.', array['Haz una bolita apretando una hoja de papel.', 'Ponla en la cuchara.', 'Que camine hasta la meta sin dejarla caer.', 'Si se cae, vuelve a empezar desde donde iba.']::text[], 'Para hacerlo más difícil, que lleve la cuchara con la mano que no usa.', true),
  ('mapa-del-tesoro', 'Mapa del tesoro', 'Dibujan un mapa y buscan el tesoro escondido.', 'Esconde un juguete y dibuja un mapa sencillo de la casa para que tu hijo lo encuentre.', 4, 5, 30, 'juntos', 'casa', array['papel', 'colores', 'un juguete para esconder']::text[], array['papel', 'colores']::text[], true, '5 minutos.', array['Esconde el juguete sin que te vea.', 'Dibuja un mapa con la sala, la cocina y una X donde está.', 'Dale el mapa y acompáñalo a buscar.', 'Después, que él esconda el tesoro y te dibuje el mapa.']::text[], 'Usa dibujos de muebles que reconozca: el sofá, la mesa, la cama.', true),
  ('parejas-de-medias', 'Parejas de medias', 'Encontrar cada media con su compañera.', 'Mezcla un montón de medias y que encuentre las parejas por color, tamaño o dibujo.', 4, 5, 15, 'aprender', 'casa', array['medias limpias de la familia']::text[], array['nada']::text[], false, '1 minuto.', array['Riega las medias en la cama o el piso.', 'Pídele que encuentre las parejas.', 'Pregunta de quién es cada par.', 'Doblen juntos las parejas.']::text[], 'Es un juego y además te ayuda con la ropa limpia.', true),
  ('titeres-de-medias', 'Títeres de medias', 'Una media vieja se convierte en un personaje.', 'Convierte medias viejas en títeres con ojos y boca de papel, y armen una función.', 4, 5, 30, 'crear', 'casa', array['medias viejas', 'papel', 'marcadores', 'cinta']::text[], array['papel', 'colores', 'cinta']::text[], true, '2 minutos.', array['Recorta ojos y boca en papel.', 'Pégalos con cinta en la media.', 'Pónganle nombre a cada títere.', 'Hagan una función detrás del sofá.']::text[], 'Graba la función con el celular: les encanta verse después.', true),
  ('el-semaforo', 'El semáforo', 'Verde corre, amarillo camina, rojo se congela.', 'Un juego de atención y movimiento: tú dices el color y tu hijo hace el movimiento.', 4, 5, 5, 'moverse', 'cualquier', '{}'::text[], array['nada']::text[], false, 'Nada.', array['Explica: verde es correr, amarillo caminar, rojo quedarse quieto.', 'Di los colores en desorden.', 'Que haga el movimiento de cada color.', 'Después, que él sea el semáforo.']::text[], 'Agrega colores nuevos: azul es saltar, morado es bailar.', true),
  ('mariposas-de-pintura', 'Mariposas de pintura', 'Pinta media hoja, dobla y aparece una mariposa.', 'Pon gotas de pintura en media hoja, dóblala y ábrela: aparece una mariposa simétrica.', 4, 5, 15, 'crear', 'casa', array['papel', 'témperas o acuarelas', 'periódico para proteger la mesa']::text[], array['papel', 'colores']::text[], true, '2 minutos.', array['Dobla la hoja por la mitad y ábrela.', 'Que ponga gotas de pintura en un solo lado.', 'Doblen y presionen con la mano.', 'Abran despacio y descubran la mariposa.']::text[], 'Cuando seque, recórtala y pégala en la ventana.', true),
  ('ciudad-de-cajas', 'Ciudad de cajas', 'Cajas vacías que se vuelven casas, tiendas y edificios.', 'Con cajas de cartón y colores, tu hijo construye su propia ciudad para jugar con sus carritos o muñecos.', 4, 5, 30, 'solo', 'casa', array['cajas de cartón', 'colores', 'cinta']::text[], array['carton', 'colores', 'cinta']::text[], false, '2 minutos.', array['Junta 3 o 4 cajas vacías.', 'Que decida qué será cada una: casa, tienda, colegio.', 'Que dibuje puertas y ventanas.', 'Únanlas con cinta para hacer calles.']::text[], 'Guarda la ciudad: puede crecer con cajas nuevas cada semana.', true),
  ('el-gran-fuerte', 'El gran fuerte', 'Cobijas, cojines y una linterna. Adentro, la historia la inventan juntos.', 'Construyan un fuerte con cobijas y sillas, y lean o inventen un cuento adentro con una linterna.', 5, 5, 30, 'juntos', 'casa', array['cobijas', 'cojines', '2 sillas', 'una linterna', 'un cuento']::text[], array['nada']::text[], true, '5 minutos.', array['Pon dos sillas separadas y cúbrelas con una cobija.', 'Llenen el piso de cojines.', 'Entren con la linterna.', 'Lean un cuento o inventen uno por turnos.']::text[], 'Apaguen las luces de la sala: la linterna lo hace mágico.', false),
  ('detective-de-letras', 'Detective de letras', 'Buscar en casa cosas que empiecen por una letra.', 'Escoge una letra y salgan a buscar objetos de la casa que empiecen con ella.', 5, 5, 15, 'aprender', 'casa', array['papel', 'un marcador']::text[], array['papel', 'colores']::text[], true, '1 minuto.', array['Escribe una letra grande en un papel, por ejemplo la M.', 'Díganla en voz alta juntos.', 'Busquen cosas que empiecen con esa letra: mesa, media, manzana.', 'Cuenten cuántas encontraron.']::text[], 'Empieza por la letra de su nombre.', true),
  ('cuento-con-tres-objetos', 'Cuento con tres objetos', 'Tres cosas al azar y una historia que las une.', 'Elijan tres objetos de la casa y armen un cuento donde los tres aparezcan.', 5, 5, 15, 'tranquilo', 'cualquier', array['3 objetos cualquiera']::text[], array['nada']::text[], true, 'Nada.', array['Que escoja tres objetos de la casa.', 'Empieza tú: Había una vez...', 'Túrnense para seguir la historia.', 'El cuento termina cuando aparecen los tres objetos.']::text[], 'No corrijas la historia: entre más loca, mejor.', true),
  ('concurso-de-aviones', 'Concurso de aviones de papel', 'Doblar, lanzar y ver cuál llega más lejos.', 'Hagan aviones de papel y organicen un concurso para ver cuál vuela más lejos.', 5, 5, 15, 'crear', 'casa', array['hojas de papel', 'colores', 'cinta para marcar la salida']::text[], array['papel', 'colores', 'cinta']::text[], true, '2 minutos.', array['Doblen juntos un avión sencillo.', 'Que lo decore con colores.', 'Marca la salida con cinta en el piso.', 'Lancen por turnos y marquen dónde cae cada uno.']::text[], 'Prueben doblar las puntas de las alas para ver qué cambia.', true),
  ('restaurante-en-casa', 'Restaurante en casa', 'Tu hijo es el mesero y tú el cliente.', 'Monten un restaurante con menú dibujado: tu hijo toma el pedido y te lo sirve.', 5, 5, 30, 'juntos', 'casa', array['papel', 'colores', 'platos y vasos']::text[], array['papel', 'colores']::text[], false, '5 minutos.', array['Dibujen juntos un menú con 3 o 4 platos.', 'Siéntate a la mesa como cliente.', 'Que te dé el menú y tome tu pedido.', 'Que te sirva y luego cambien de papel.']::text[], 'Hazlo a la hora de la merienda y que sirva comida de verdad.', true),
  ('yoga-de-animales', 'Yoga de animales', 'Posturas de gato, perro, flamenco y serpiente.', 'Un rato tranquilo de movimiento imitando posturas de animales y respirando despacio.', 5, 5, 15, 'tranquilo', 'cualquier', array['una toalla o tapete']::text[], array['nada']::text[], true, 'Nada.', array['Extiendan la toalla en el piso.', 'Hagan el gato: en cuatro patas, espalda arriba y abajo.', 'Hagan el flamenco: en un pie, contando hasta 5.', 'Terminen acostados, respirando como serpientes: sssss.']::text[], 'Ideal antes de dormir o después de un día movido.', true),
  ('circuito-de-obstaculos', 'Circuito de obstáculos', 'Pasar por debajo, saltar por encima y gatear.', 'Arma un recorrido por la sala con cojines, sillas y cinta para gatear, saltar y equilibrarse.', 5, 5, 30, 'moverse', 'casa', array['cojines', '2 sillas', 'cinta de enmascarar']::text[], array['cinta']::text[], true, '5 minutos.', array['Pon cojines para saltar entre ellos.', 'Pasa una cobija entre dos sillas para gatear por debajo.', 'Pega una línea de cinta para caminar en equilibrio.', 'Que haga el circuito completo y cronometra cada vuelta.']::text[], 'Pídele que te ayude a diseñar el circuito.', true),
  ('sombras-con-linterna', 'Sombras con linterna', 'Perros, pájaros y monstruos en la pared.', 'Apaguen la luz y hagan figuras con las manos frente a una linterna.', 5, 5, 15, 'tranquilo', 'casa', array['una linterna', 'una pared clara']::text[], array['nada']::text[], true, '1 minuto.', array['Apaguen la luz y apunten la linterna a la pared.', 'Hazle una figura con las manos: un pájaro o un perro.', 'Que intente copiarla.', 'Inventen una historia con las sombras.']::text[], 'Usa la linterna del celular si no tienes otra.', true)
